import os

import mlflow
import mlflow.tracking
from fastapi import FastAPI, HTTPException
from pydantic import BaseModel

# Set MLflow tracking URI
mlflow.set_tracking_uri("http://127.0.0.1:5000")

app = FastAPI()

# Global variables to hold model and info
_model = None
_model_info = None

def load_model_from_registry():
    """Load the registered model from MLflow Model Registry"""
    client = mlflow.tracking.MlflowClient()
    # Get the model version in Production stage
    versions = client.search_model_versions(name="breast-cancer-classifier", stages=["Production"])
    if not versions:
        raise Exception("No model found in Production stage")
    mv = versions[0]  # Get the Production version
    model_version = mv.version
    model_uri = f"models:/breast-cancer-classifier/{model_version}"
    model = mlflow.load_model(model_uri)
    # Get the run_id that created this version
    run_id = mv.run_id
    run = client.get_run(run_id)
    model_type = run.data.params.get("model_type", "unknown")
    _model_info = {
        "model_name": "breast-cancer-classifier",
        "model_version": int(model_version),
        "model_stage": "Production",
        "model_type": model_type
    }
    global _model, _model_info
    _model = model
    return model, _model_info

@app.on_event("startup")
def startup_event():
    """Load the model from MLflow registry at startup"""
    load_model_from_registry()

class PredictRequest(BaseModel):
    features: list[float]

class PredictBatchRequest(BaseModel):
    samples: list[list[float]]

@app.post("/predict")
def predict(request: PredictRequest):
    """Predict for a single sample"""
    if len(request.features) != 30:
        raise HTTPException(status_code=400, detail="features must contain exactly 30 float values")
    prediction = _model.predict([[request.features]])[0]
    prediction_label = "malignant" if prediction == 0 else "benign"
    return {
        "prediction": int(prediction),
        "prediction_label": prediction_label,
        "model_name": _model_info["model_name"],
        "model_version": _model_info["model_version"]
    }

@app.get("/health")
def health():
    """Health check endpoint"""
    return {
        "status": "healthy",
        "model_loaded": _model is not None,
        "mlflow_tracking_uri": "http://127.0.0.1:5000"
    }

@app.get("/model-info")
def model_info():
    """Return model information"""
    return {
        "model_name": _model_info["model_name"],
        "model_version": _model_info["model_version"],
        "model_stage": _model_info["model_stage"],
        "model_type": _model_info["model_type"]
    }

@app.post("/predict-batch")
def predict_batch(request: PredictBatchRequest):
    """Predict for multiple samples"""
    if not request.samples:
        raise HTTPException(status_code=422, detail="samples list cannot be empty")
    for sample in request.samples:
        if len(sample) != 30:
            raise HTTPException(status_code=400, detail="each sample must contain exactly 30 float values")

    predictions = []
    for sample in request.samples:
        pred = _model.predict([[sample]])[0]
        prediction_label = "malignant" if pred == 0 else "benign"
        predictions.append({
            "prediction": int(pred),
            "prediction_label": prediction_label
        })
    return {
        "predictions": predictions,
        "count": len(request.samples),
        "model_name": _model_info["model_name"],
        "model_version": _model_info["model_version"]
    }
